export function getEntityDefinition(family: ToolFamilyKey, toolTitle: string, locale: SupportedLocale = "en"): string {
  const famDict = ENTITY_TEMPLATES[family] || ENTITY_TEMPLATES.pdf;
  const template = famDict[locale] || famDict.en;
  return template(toolTitle);
}
